class TestFeedbackModels(unittest.TestCase):
    """Testy Feedback Models."""
    
    def setUp(self):
        """Setup."""
        self.maxDiff = None
    
    def test_prediction_outcome_creation(self):
        """Test tworzenia PredictionOutcome."""
        outcome = PredictionOutcome(
            strategy_id="test_strategy",
            predicted_result="1",
            actual_result="1"
        )
        self.assertEqual(outcome.strategy_id, "test_strategy")
        self.assertEqual(outcome.predicted_result, "1")
        self.assertEqual(outcome.actual_result, "1")
    
    def test_prediction_outcome_calculate_scores_exact(self):
        """Test obliczania wyników - dokładne trafienie."""
        outcome = PredictionOutcome(
            strategy_id="test",
            predicted_result="1",
            actual_result="1",
            predicted_home_goals=2,
            predicted_away_goals=1,
            actual_home_goals=2,
            actual_away_goals=1
        )
        outcome.calculate_scores()
        
        self.assertTrue(outcome.exact_score)
        self.assertTrue(outcome.result_correct)
        self.assertTrue(outcome.goals_correct)
        self.assertTrue(outcome.is_exact())
        self.assertTrue(outcome.is_correct())
    
    def test_prediction_outcome_calculate_scores_partial(self):
        """Test obliczania wyników - częściowo poprawne."""
        outcome = PredictionOutcome(
            strategy_id="test",
            predicted_result="1",
            actual_result="1",
            predicted_home_goals=3,
            predicted_away_goals=0,
            actual_home_goals=2,
            actual_away_goals=1
        )
        outcome.calculate_scores()
        
        self.assertFalse(outcome.exact_score)
        self.assertTrue(outcome.result_correct)
        self.assertFalse(outcome.goals_correct)
        self.assertFalse(outcome.is_exact())
        self.assertTrue(outcome.is_correct())
    
    def test_prediction_outcome_calculate_scores_wrong(self):
        """Test obliczania wyników - zupełnie błędne."""
        outcome = PredictionOutcome(
            strategy_id="test",
            predicted_result="1",
            actual_result="2"
        )
        outcome.calculate_scores()
        
        self.assertFalse(outcome.exact_score)
        self.assertFalse(outcome.result_correct)
        self.assertFalse(outcome.is_exact())
        self.assertFalse(outcome.is_correct())
    
    def test_strategy_fitness_add_outcome(self):
        """Test dodawania outcome do StrategyFitness."""
        fitness = StrategyFitness(strategy_id="test_strategy")
        
        # Dodaj poprawną predykcję
        outcome = PredictionOutcome(
            strategy_id="test_strategy",
            predicted_result="1",
            actual_result="1"
        )
        outcome.calculate_scores()
        fitness.add_prediction_outcome(outcome)
        
        self.assertEqual(fitness.total_predictions, 1)
        self.assertEqual(fitness.correct_predictions, 1)
    
    def test_strategy_fitness_ranking(self):
        """Test rankingu strategii."""
        fitness = StrategyFitness(
            strategy_id="test",
            overall_fitness=0.95,
            accuracy=0.95
        )
        self.assertEqual(fitness.get_ranking(), "A+ (EXCELLENT)")
    
