class TestPredictionEvaluator(unittest.TestCase):
    """Testy PredictionEvaluator."""
    
    def setUp(self):
        """Setup."""
        self.evaluator = PredictionEvaluator()
    
    def test_exact_match_evaluation(self):
        """Test ewaluacji - dokładne trafienie."""
        prediction_trace = {
            'trace_id': 'trace_001',
            'prediction': {
                'result': '1',
                'confidence': 0.8,
                'model_output': {'home_goals': 2, 'away_goals': 1}
            }
        }
        
        match_result = {
            'match_id': 'match_001',
            'home_goals': 2,
            'away_goals': 1,
            'result': '1'
        }
        
        evaluation = self.evaluator.evaluate(prediction_trace, match_result)
        
        self.assertTrue(evaluation.exact_score)
        self.assertTrue(evaluation.result_correct)
        self.assertEqual(evaluation.status, EvaluationStatus.EXACT)
        self.assertEqual(evaluation.accuracy_score, 1.0)
    
    def test_result_correct_goals_wrong(self):
        """Test ewaluacji - poprawny wynik, błędne gole."""
        prediction_trace = {
            'trace_id': 'trace_002',
            'prediction': {
                'result': '1',
                'model_output': {'home_goals': 3, 'away_goals': 0}
            }
        }
        
        match_result = {
            'match_id': 'match_002',
            'home_goals': 2,
            'away_goals': 1,
            'result': '1'
        }
        
        evaluation = self.evaluator.evaluate(prediction_trace, match_result)
        
        self.assertFalse(evaluation.exact_score)
        self.assertTrue(evaluation.result_correct)
        self.assertEqual(evaluation.status, EvaluationStatus.PARTIAL)
        self.assertGreater(evaluation.accuracy_score, 0)
        self.assertLess(evaluation.accuracy_score, 1.0)
    
    def test_completely_wrong_prediction(self):
        """Test ewaluacji - zupełnie błędna predykcja."""
        prediction_trace = {
            'trace_id': 'trace_003',
            'prediction': {
                'result': '1',
                'model_output': {'home_goals': 3, 'away_goals': 0}
            }
        }
        
        match_result = {
            'match_id': 'match_003',
            'home_goals': 0,
            'away_goals': 2,
            'result': '2'
        }
        
        evaluation = self.evaluator.evaluate(prediction_trace, match_result)
        
        self.assertFalse(evaluation.exact_score)
        self.assertFalse(evaluation.result_correct)
        self.assertEqual(evaluation.status, EvaluationStatus.INCORRECT)
        self.assertEqual(evaluation.accuracy_score, 0.0)
    
    def test_draw_prediction(self):
        """Test ewaluacji - remis."""
        prediction_trace = {
            'trace_id': 'trace_004',
            'prediction': {
                'result': 'X',
                'model_output': {'home_goals': 1, 'away_goals': 1}
            }
        }
        
        match_result = {
            'match_id': 'match_004',
            'home_goals': 1,
            'away_goals': 1,
            'result': 'X'
        }
        
        evaluation = self.evaluator.evaluate(prediction_trace, match_result)
        
        self.assertTrue(evaluation.exact_score)
        self.assertTrue(evaluation.result_correct)
        self.assertEqual(evaluation.status, EvaluationStatus.EXACT)
    
    def test_conversion_to_outcome(self):
        """Test konwersji EvaluationResult do PredictionOutcome."""
        prediction_trace = {
            'trace_id': 'trace_005',
            'prediction': {'result': '1', 'model_output': {'home_goals': 2, 'away_goals': 1}}
        }
        
        match_result = {
            'match_id': 'match_005',
            'home_goals': 2,
            'away_goals': 1,
            'result': '1'
        }
        
        outcome = self.evaluator.evaluate_to_outcome(prediction_trace, match_result)
        
        self.assertIsInstance(outcome, PredictionOutcome)
        self.assertTrue(outcome.exact_score)
        self.assertTrue(outcome.result_correct)
    
    def test_batch_evaluation(self):
        """Test ewaluacji batch."""
        traces = [
            {'trace_id': f'trace_{i}', 'prediction': {'result': '1', 'model_output': {'home_goals': 2, 'away_goals': 1}}}
            for i in range(3)
        ]
        
        results_list = [
            {'match_id': f'match_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'}
            for i in range(3)
        ]
        
        evaluations = self.evaluator.evaluate_batch(traces, results_list)
        
        self.assertEqual(len(evaluations), 3)
        self.assertTrue(all(e.exact_score for e in evaluations))
    
    def test_evaluator_reset(self):
        """Test resetu ewaluatora."""
        self.evaluator.evaluate(
            {'prediction': {'result': '1'}},
            {'home_goals': 2, 'away_goals': 1, 'result': '1'}
        )
        
        self.assertGreater(self.evaluator.evaluation_count, 0)
        
        self.evaluator.reset()
        
        self.assertEqual(self.evaluator.evaluation_count, 0)
        self.assertEqual(len(self.evaluator.events), 0)
    
    def test_evaluator_statistics(self):
        """Test statystyk ewaluatora."""
        self.evaluator.evaluate(
            {'prediction': {'result': '1'}},
            {'home_goals': 2, 'away_goals': 1, 'result': '1'}
        )
        
        stats = self.evaluator.get_statistics()
        
        self.assertIn('total_evaluations', stats)
        self.assertIn('success_count', stats)
        self.assertIn('events', stats)


