class TestFitnessCalculator(unittest.TestCase):
    """Testy StrategyFitnessCalculator."""
    
    def setUp(self):
        """Setup."""
        self.calculator = StrategyFitnessCalculator()
    
    def _create_outcome(self, correct: bool = True, exact: bool = True):
        """Helper: Tworzy PredictionOutcome."""
        outcome = PredictionOutcome(
            strategy_id="test_strategy",
            predicted_result="1" if correct else "2",
            actual_result="1",
            predicted_home_goals=2,
            predicted_away_goals=1,
            actual_home_goals=2,
            actual_away_goals=1
        )
        if exact and correct:
            outcome.predicted_home_goals = 2
            outcome.predicted_away_goals = 1
        elif correct:
            outcome.predicted_home_goals = 3
            outcome.predicted_away_goals = 0
        else:
            outcome.predicted_result = "2"
        
        outcome.calculate_scores()
        return outcome
    
    def test_perfect_fitness(self):
        """Test fitness dla idealnej strategii."""
        outcomes = [self._create_outcome(True, True) for _ in range(5)]
        
        fitness = self.calculator.calculate_fitness("perfect_strategy", outcomes)
        
        self.assertEqual(fitness.accuracy, 1.0)
        self.assertEqual(fitness.exact_accuracy, 1.0)
        self.assertEqual(fitness.overall_fitness, 1.0)
    
    def test_zero_fitness(self):
        """Test fitness dla zupełnie złej strategii."""
        outcomes = [self._create_outcome(False, False) for _ in range(5)]
        
        fitness = self.calculator.calculate_fitness("bad_strategy", outcomes)
        
        self.assertEqual(fitness.accuracy, 0.0)
        self.assertEqual(fitness.correct_predictions, 0)
        self.assertEqual(fitness.overall_fitness, 0.0)
    
    def test_partial_fitness(self):
        """Test fitness dla częściowo poprawnej strategii."""
        outcomes = [
            self._create_outcome(True, True),  # 1 poprawne
            self._create_outcome(True, True),  # 2 poprawne
            self._create_outcome(False, False), # 1 błędne
        ]
        
        fitness = self.calculator.calculate_fitness("partial_strategy", outcomes)
        
        self.assertEqual(fitness.total_predictions, 3)
        self.assertEqual(fitness.correct_predictions, 2)
        self.assertGreater(fitness.overall_fitness, 0)
        self.assertLess(fitness.overall_fitness, 1.0)
    
    def test_fitness_from_outcomes(self):
        """Test calculate_from_outcomes."""
        outcomes = [
            PredictionOutcome(
                strategy_id="strategy_A",
                predicted_result="1",
                actual_result="1"
            ),
            PredictionOutcome(
                strategy_id="strategy_B",
                predicted_result="1",
                actual_result="2"
            )
        ]
        
        for o in outcomes:
            o.calculate_scores()
        
        fitness_values = self.calculator.calculate_from_outcomes(outcomes)
        
        self.assertEqual(len(fitness_values), 2)
        self.assertIn("strategy_A", fitness_values)
        self.assertIn("strategy_B", fitness_values)
    
    def test_ranking_strategies(self):
        """Test rankingu strategii."""
        fitness_values = {
            "strategy_1": StrategyFitness(strategy_id="strategy_1", overall_fitness=0.9),
            "strategy_2": StrategyFitness(strategy_id="strategy_2", overall_fitness=0.7),
            "strategy_3": StrategyFitness(strategy_id="strategy_3", overall_fitness=0.5),
        }
        
        ranked = self.calculator.rank_strategies(fitness_values)
        
        self.assertEqual(len(ranked), 3)
        self.assertEqual(ranked[0][0], "strategy_1")
        self.assertEqual(ranked[1][0], "strategy_2")
        self.assertEqual(ranked[2][0], "strategy_3")
    
    def test_top_n_strategies(self):
        """Test top N strategii."""
        fitness_values = {
            f"strategy_{i}": StrategyFitness(
                strategy_id=f"strategy_{i}",
                overall_fitness=1.0 - (i * 0.1)
            )
            for i in range(5)
        }
        
        top_3 = self.calculator.get_top_n(fitness_values, n=3)
        
        self.assertEqual(len(top_3), 3)
        self.assertEqual(top_3[0][0], "strategy_0")
        self.assertEqual(top_3[1][0], "strategy_1")
        self.assertEqual(top_3[2][0], "strategy_2")
    
    def test_fitness_components(self):
        """Test składników fitness."""
        outcomes = [self._create_outcome(True, True) for _ in range(3)]
        
        components = self.calculator.get_components(outcomes)
        
        self.assertIsInstance(components, FitnessComponents)
        self.assertGreater(components.accuracy_component, 0)
    
    def test_calculator_reset(self):
        """Test resetu kalkulatora."""
        self.calculator.calculate_fitness("test", [self._create_outcome(True, True)])
        
        self.assertGreater(self.calculator.evaluation_count, 0)
        
        self.calculator.reset()
        
        self.assertEqual(self.calculator.evaluation_count, 0)


