class TestFeedbackEngine(unittest.TestCase):
    """Testy FeedbackEngine."""
    
    def setUp(self):
        """Setup."""
        TestConfiguration.setup_temp_dir()
        config = FeedbackConfig(
            memory_dir=TestConfiguration.TEMP_DIR,
            events_log_file="test_events.json"
        )
        self.engine = FeedbackEngine(config=config)
    
    def tearDown(self):
        """Cleanup."""
        TestConfiguration.cleanup_temp_dir()
    
    def test_engine_initialization(self):
        """Test inicjalizacji silnika."""
        self.assertIsNotNone(self.engine)
        self.assertIsNotNone(self.engine.config)
        self.assertIsNotNone(self.engine.evaluator)
        self.assertIsNotNone(self.engine.fitness_calculator)
    
    def test_simple_feedback_cycle(self):
        """Test prostego cyklu feedback."""
        prediction_trace = {
            'trace_id': 'trace_001',
            'prediction': {
                'result': '1',
                'confidence': 0.8,
                'model_output': {'home_goals': 2, 'away_goals': 1}
            }
        }
        
        match_result = {
            'match_id': 'match_001',
            'home_goals': 2,
            'away_goals': 1,
            'result': '1'
        }
        
        context = self.engine.process_feedback_cycle(
            prediction_trace, match_result, 'test_strategy'
        )
        
        self.assertIsNotNone(context)
        self.assertEqual(context.status, "completed")
        self.assertIsNotNone(context.evaluation_result)
        self.assertIsNotNone(context.prediction_outcome)
        self.assertTrue(context.prediction_outcome.exact_score)
        self.assertEqual(self.engine.total_cycles, 1)
    
    def test_multiple_feedback_cycles(self):
        """Test wielu cykli feedback."""
        for i in range(5):
            prediction_trace = {
                'trace_id': f'trace_{i}',
                'prediction': {'result': '1'}
            }
            
            match_result = {
                'match_id': f'match_{i}',
                'home_goals': 2,
                'away_goals': 1,
                'result': '1'
            }
            
            self.engine.process_feedback_cycle(
                prediction_trace, match_result, 'multi_strategy'
            )
        
        self.assertEqual(self.engine.total_cycles, 5)
        self.assertEqual(self.engine.successful_cycles, 5)
        
        # Sprawdź fitness
        fitness = self.engine.get_strategy_fitness('multi_strategy')
        self.assertIsNotNone(fitness)
        self.assertEqual(fitness.total_predictions, 5)
        self.assertEqual(fitness.correct_predictions, 5)
    
    def test_mixed_results(self):
        """Test mieszanych wyników (poprawne i błędne)."""
        # 3 poprawne, 2 błędne
        for i in range(5):
            prediction_trace = {
                'trace_id': f'trace_{i}',
                'prediction': {'result': '1'}
            }
            
            if i < 3:
                match_result = {'match_id': f'match_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'}
            else:
                match_result = {'match_id': f'match_{i}', 'home_goals': 0, 'away_goals': 2, 'result': '2'}
            
            self.engine.process_feedback_cycle(
                prediction_trace, match_result, 'mixed_strategy'
            )
        
        fitness = self.engine.get_strategy_fitness('mixed_strategy')
        self.assertIsNotNone(fitness)
        self.assertEqual(fitness.correct_predictions, 3)
        self.assertEqual(fitness.failed_predictions, 2)
        self.assertGreater(fitness.overall_fitness, 0)
        self.assertLess(fitness.overall_fitness, 1.0)
    
    def test_batch_processing(self):
        """Test przetwarzania batch."""
        traces = [
            {'trace_id': f'trace_{i}', 'prediction': {'result': '1'}}
            for i in range(3)
        ]
        
        results_list = [
            {'match_id': f'match_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'}
            for i in range(3)
        ]
        
        contexts = self.engine.process_batch(
            traces, results_list, ['batch_strategy'] * 3
        )
        
        self.assertEqual(len(contexts), 3)
        self.assertTrue(all(c.status == "completed" for c in contexts))
        
        fitness = self.engine.get_strategy_fitness('batch_strategy')
        self.assertEqual(fitness.total_predictions, 3)
    
    def test_strategy_ranking(self):
        """Test rankingu strategii."""
        # Strategia A: 100% poprawnych
        for i in range(3):
            self.engine.process_feedback_cycle(
                {'trace_id': f'trace_A_{i}', 'prediction': {'result': '1'}},
                {'match_id': f'match_A_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
                'strategy_A'
            )
        
        # Strategia B: 0% poprawnych
        for i in range(3):
            self.engine.process_feedback_cycle(
                {'trace_id': f'trace_B_{i}', 'prediction': {'result': '1'}},
                {'match_id': f'match_B_{i}', 'home_goals': 0, 'away_goals': 2, 'result': '2'},
                'strategy_B'
            )
        
        ranking = self.engine.get_ranking()
        
        self.assertEqual(len(ranking), 2)
        self.assertEqual(ranking[0][0], 'strategy_A')
        self.assertEqual(ranking[1][0], 'strategy_B')
    
    def test_get_top_strategy(self):
        """Test pobierania najlepszej strategii."""
        for i in range(3):
            self.engine.process_feedback_cycle(
                {'trace_id': f'trace_{i}', 'prediction': {'result': '1'}},
                {'match_id': f'match_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
                'top_strategy'
            )
        
        top = self.engine.get_top_strategy()
        
        self.assertIsNotNone(top)
        self.assertEqual(top[0], 'top_strategy')
        self.assertEqual(top[1].overall_fitness, 1.0)
    
    def test_feedback_report(self):
        """Test generowania raportu feedback."""
        for i in range(3):
            self.engine.process_feedback_cycle(
                {'trace_id': f'trace_{i}', 'prediction': {'result': '1'}},
                {'match_id': f'match_{i}', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
                'report_strategy'
            )
        
        report = self.engine.get_feedback_report()
        
        self.assertIsNotNone(report)
        self.assertIn('statistics', report)
        self.assertIn('ranking', report)
        self.assertIn('top_strategy', report)
        self.assertIn('events_summary', report)
    
    def test_engine_statistics(self):
        """Test statystyk silnika."""
        self.engine.process_feedback_cycle(
            {'trace_id': 'trace_1', 'prediction': {'result': '1'}},
            {'match_id': 'match_1', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
            'stats_strategy'
        )
        
        stats = self.engine.get_statistics()
        
        self.assertIn('engine', stats)
        self.assertIn('evaluator', stats)
        self.assertIn('fitness_calculator', stats)
        self.assertEqual(stats['engine']['total_cycles'], 1)
    
    def test_engine_reset(self):
        """Test resetu silnika."""
        self.engine.process_feedback_cycle(
            {'trace_id': 'trace_1', 'prediction': {'result': '1'}},
            {'match_id': 'match_1', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
            'reset_strategy'
        )
        
        self.assertGreater(self.engine.total_cycles, 0)
        
        self.engine.reset()
        
        self.assertEqual(self.engine.total_cycles, 0)
        self.assertEqual(len(self.engine.outcomes), 0)
        self.assertEqual(len(self.engine.fitness_values), 0)
    
    def test_invalid_input(self):
        """Test obsługi błędnych danych wejściowych."""
        # Brak match_result
        context = self.engine.process_feedback_cycle(
            {'trace_id': 'trace_1', 'prediction': {'result': '1'}},
            None,
            'error_strategy'
        )
        
        self.assertEqual(context.status, "failed")
        self.assertGreater(len(context.errors), 0)


