class TestFeedbackIntegration(unittest.TestCase):
    """Testy integracyjne."""
    
    def setUp(self):
        """Setup."""
        TestConfiguration.setup_temp_dir()
    
    def tearDown(self):
        """Cleanup."""
        TestConfiguration.cleanup_temp_dir()
    
    def test_full_feedback_loop(self):
        """Test pełnej pętli feedback."""
        # Tworzymy engine
        config = FeedbackConfig(memory_dir=TestConfiguration.TEMP_DIR)
        engine = FeedbackEngine(config=config)
        
        # Symulujemy prediction trace z Prediction Trace Engine
        prediction_trace = {
            'trace_id': 'ptr_001',
            'prediction_id': 'pred_001',
            'strategy_id': 'integration_strategy',
            'context': {'world_version': 'v1.0', 'cycle_id': 'cycle_001'},
            'model': {'reference': 'test_model', 'version': '1.0'},
            'prediction': {
                'result': '1',
                'confidence': 0.85,
                'prediction_type': 'classification',
                'model_output': {'home_goals': 2, 'away_goals': 1}
            },
            'strategy_experiment_id': 'exp_001',
            'world_engine_cycle_id': 'world_cycle_001'
        }
        
        # Symulujemy result z Result Ingestion
        match_result = {
            'match_id': 'match_001',
            'home_team': 'Team A',
            'away_team': 'Team B',
            'home_goals': 2,
            'away_goals': 1,
            'result': '1',
            'source': 'test_csv.csv',
            'created_at': datetime.now().isoformat()
        }
        
        # Przetwarzamy
        context = engine.process_feedback_cycle(
            prediction_trace, match_result, 'integration_strategy'
        )
        
        # Weryfikujemy
        self.assertEqual(context.status, "completed")
        self.assertIsNotNone(context.evaluation_result)
        self.assertIsNotNone(context.prediction_outcome)
        self.assertIsNotNone(context.strategy_fitness)
        
        # Sprawdź fitness
        fitness = context.strategy_fitness
        self.assertEqual(fitness.strategy_id, 'integration_strategy')
        self.assertEqual(fitness.overall_fitness, 1.0)
    
    def test_memory_persistence(self):
        """Test persystencji pamięci."""
        config = FeedbackConfig(
            memory_dir=TestConfiguration.TEMP_DIR,
            enable_memory_persistence=True
        )
        engine = FeedbackEngine(config=config)
        
        # Przetwórz cykl
        engine.process_feedback_cycle(
            {'trace_id': 'trace_1', 'prediction': {'result': '1'}},
            {'match_id': 'match_1', 'home_goals': 2, 'away_goals': 1, 'result': '1'},
            'memory_strategy'
        )
        
        # Sprawdź plik pamięci
        memory_file = Path(TestConfiguration.TEMP_DIR) / "strategy_feedback_memory.json"
        self.assertTrue(memory_file.exists())
        
        # Wczytanie danych
        with open(memory_file, 'r') as f:
            data = json.load(f)
        
        self.assertIn('outcomes', data)
        self.assertIn('fitness_values', data)
    
    def test_external_integration_mock(self):
        """Test integracji z zewnętrznymi modułami (mock)."""
        engine = FeedbackEngine()
        
        # Mock Strategy Memory Manager
        class MockStrategyMemoryManager:
            def __init__(self):
                self.records = {}
            
            def get_strategy_memory(self, strategy_id):
                return self.records.get(strategy_id)
            
            def create_strategy_memory(self, strategy_id, strategy_version):
                from SSI_V5.memory.strategy_memory import StrategyMemoryRecord
                record = StrategyMemoryRecord(
                    strategy_id=strategy_id,
                    strategy_version=strategy_version
                )
                self.records[strategy_id] = record
                return record
            
            def _save_record(self, record):
                pass
        
        # Podłącz mock
        engine.connect_to_strategy_memory(MockStrategyMemoryManager())
        
        self.assertIsNotNone(engine._strategy_memory_manager)
    
    def test_pipeline_customization(self):
        """Test dostosowania pipeline."""
        # Custom pipeline
        engine = FeedbackEngine()
        
        # Początkowo pipeline ma kroki
        initial_steps = len(engine.pipeline.steps)
        self.assertGreater(initial_steps, 0)
        
        # Możemy dodać własne kroki
        engine.pipeline.add_step("custom_step", lambda ctx: True)
        
        # Powinien być nowy krok
        self.assertEqual(len(engine.pipeline.steps), initial_steps + 1)


# ============================================================================
# MAIN TEST RUNNER
# ============================================================================

def run_all_tests():
    """Uruchamia wszystkie testy."""
    print("\n" + "="*80)
    print("SSI V5 FEEDBACK MODULE - COMPREHENSIVE TESTS")
    print("="*80)
    
    # Lista testów
    test_classes = [
        TestFeedbackModels,
        TestPredictionEvaluator,
        TestFitnessCalculator,
        TestFeedbackEngine,
        TestFeedbackIntegration
    ]
    
    # Uruchom wszystkie testy
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()
    
    for test_class in test_classes:
        suite.addTests(loader.loadTestsFromTestCase(test_class))
    
    # Run tests
    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)
    
    # Podsumowanie
    print("\n" + "="*80)
    print("PODSUMOWANIE TESTOW")
    print("="*80)
    print(f"Uruchomiono: {result.testsRun} testow")
    print(f"Zaliczono: {result.testsRun - len(result.failures) - len(result.errors)}")
    print(f"Bledy: {len(result.errors)}")
    print(f"Failury: {len(result.failures)}")
    print(f"Czas: {result.time:.4f}s")
    
    # Sprawdź minimum 40 testów
    if result.testsRun >= 40:
        print(f"\n✅ MINIMUM 40 TESTOW: {result.testsRun} > 40")
    else:
        print(f"\n❌ MINIMUM 40 TESTOW: {result.testsRun} < 40")
    
    # Sprawdź sukces
    if result.wasSuccessful():
        print("\n✅ WSZYSTKIE TESTY ZALICZONE!")
        return True
    else:
        print("\n❌ NIEKTORY TESTY NIE ZOSTALY ZALICZONE")
        return False


if __name__ == "__main__":
    success = run_all_tests()
    sys.exit(0 if success else 1)
